script:
import { stage, sleep, observe, resumeWhen, tap, log, stop } from "klickr";
await stage("Conferir painel compacto", "Painel compacto: área de lançamento livre.");
await sleep(30000);
await resumeWhen({kind:"color",reference:"background",threshold:0,region:{left:50,top:400,right:100,bottom:450}});
let frame = await observe();
await tap({x:600,y:260,frame:frame.frame});
await log("Ponto de lançamento livre sem pausa.");
await sleep(5000);
frame = await observe();
await tap({x:280,y:150,frame:frame.frame});
await log("Retomada humana após proteção do painel compacto.");
await stop("Conferência do painel compacto concluída.");
